KG42.register("source_edge_archive-1fbdb32f90a1c2589925737d",{"id":"05-double_auction::v141-c-R025::E::v141-c-R025-E001","paper":"05-double_auction","rule_id":"v141-c-R025","rule_ref":"05-double_auction::v141-c-R025","record":{"edge_id":"v141-c-R025-E001","source":"pricing.local","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R025-C001"],"evidence_ids":["v141-b-g01-ev-06","v141-b-g01-ev-08"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R025-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-d4d038c21a480e0b","target":"COMP-67068978718ed583","source_occurrence_id":"05-double_auction::v141-c-R025::V::pricing.local","target_occurrence_id":"05-double_auction::v141-c-R025::V::settlement.payment","source_unit_id":"05-double_auction::v141-a-M04::pricing.local","target_unit_id":"05-double_auction::v141-a-M04::settlement.payment","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Trading buyers and sellers under the TR auction payment rule reviewed for local P2P energy trading.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-06","v141-b-g01-ev-08"]},"active":true,"source_signature":"9423eec02f65d6d94e1a7e11ca2515c024b8e2b16b5f0b8024597196553a9f33","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M04","source_definition":"After excluding the marginal gamma pair, buyers pay B_gamma and sellers receive S_gamma. Do not replace the distinct rates with their midpoint or a common clearing price.","target_definition":"Monetary obligations, transfers, sharing or settlement conditions in this mechanism: Exclude the marginal gamma buyer/seller pair; gamma-1 pairs trade, buyers paying the marginal bid and sellers receiving the marginal ask.","constraints":[{"constraint_id":"v141-c-R025-C001","kind":"mathematical","role":"core","statement":"Local TR transaction prices determine buyers' payment rates as B_γ^P and sellers' receipt rates as S_γ^P. Scope: Trading buyers and sellers under the TR auction payment rule reviewed for local P2P energy trading.","expression":"\\text{Buyer payment rate} = B_{\\gamma}^{P}, \\quad \\text{Seller receipt rate} = S_{\\gamma}^{P}","formalization_origin":"source","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":["v141-c-R025-theta-BgammaP","v141-c-R025-theta-SgammaP"],"evidence_ids":["v141-b-g01-ev-06","v141-b-g01-ev-08"]}],"evidence":[{"evidence_id":"v141-b-g01-ev-06","location":{"location_id":"src-22913ad574-p02-c2r4__v141-a-M04-pricing","page":2,"printed_page":null,"section":"2.1","anchor_text":"a y g g p s- does not exist for each auction interval. of Uniform k-DA is a variation to discriminat","equation_id":null,"figure_id":null,"table_id":"Table 1","image_ref":"pages/page-02.png","occurrence_role":"formula"},"source_text":"Table 1 Auction mechanisms. TR | Price trading buyers pay: $B_{\\gamma}^P$ | Price trading sellers receive: $S_{\\gamma}^P$"},{"evidence_id":"v141-b-g01-ev-08","location":{"location_id":"src-22913ad574-p03-c1r2__v141-a-M04-clearing","page":3,"printed_page":null,"section":"2.1","anchor_text":"of trades while maintaining truthful bidding by limiting trades to 1 Ta buyers and sellers [45]. Suc","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The Trade Reduction (TR) auction mechanism avoids subsidization of trades while maintaining truthful bidding by limiting trades to $\\gamma - 1$ buyers and sellers [45]. Such differs from uniform k-DA and VCG, where $\\gamma$ buyers and sellers are allowed to transact. Because buyer $\\gamma$ and seller $\\gamma$ are not permitted to participate in the TR auction, social welfare is not maximized. However, trading buyers pay $B_{\\gamma}^P$ and trading sellers receive $S_{\\gamma}^P$. As $B_{\\gamma}^P \\geq S_{\\gamma}^P$, the market operator may financially gain $B_{\\gamma}^P - S_{\\gamma}^P$ from each single unit transaction."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Trading buyers and sellers under the TR auction payment rule reviewed for local P2P energy trading.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-06","v141-b-g01-ev-08"]},"source_record":{"edge_id":"v141-c-R025-E001","source":"pricing.local","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R025-C001"],"evidence_ids":["v141-b-g01-ev-06","v141-b-g01-ev-08"]},"paper_scope_note":"The four auctions are kept separate; the time-period conditions of marginal index, buy/sell eligibility, price bound, shortfall subsidy, and historical price are retained. What is cited is the mechanism description given in the paper and is not expanded to all VCG definitions."}});
